import pandas as pd
import numpy as np


def run(inputs: dict) -> dict:
    target_state = inputs["target_state"].copy()
    cdc_events = inputs["cdc_events"].copy()

    # At-least-once delivery -> apply each seq only once.
    cdc_events = cdc_events.drop_duplicates(subset=["seq"], keep="first")

    # Build a lookup of the current target state per order_id.
    target_dict = {}
    for _, row in target_state.iterrows():
        oid = int(row["order_id"])
        target_dict[oid] = {
            "status": row["status"],
            "amount": row["amount"],
            "last_seq": int(row["last_seq"]),
        }

    # Group cdc events per order, sorted by seq (the only trustworthy order).
    events_by_order = {}
    if not cdc_events.empty:
        for oid, grp in cdc_events.groupby("order_id"):
            events_by_order[int(oid)] = grp.sort_values("seq")

    all_order_ids = set(target_dict.keys()) | set(events_by_order.keys())

    new_state_rows = []
    tombstone_rows = []

    for oid in all_order_ids:
        if oid in target_dict:
            status = target_dict[oid]["status"]
            amount = target_dict[oid]["amount"]
            last_seq = target_dict[oid]["last_seq"]
            has_row = True
            had_row_ever = True
            guard_seq = last_seq
        else:
            status = None
            amount = None
            last_seq = None
            has_row = False
            had_row_ever = False
            guard_seq = None

        last_applied_op = None
        last_applied_seq = None

        events = events_by_order.get(oid)
        if events is not None:
            for _, ev in events.iterrows():
                seq = int(ev["seq"])

                # Replay guard: skip events already reflected in the
                # original target_state (based on the row's last_seq at
                # the start, not the evolving in-batch state).
                if guard_seq is not None and seq <= guard_seq:
                    continue

                op = ev["op"]
                ev_status = ev["status"]
                ev_amount = ev["amount"]

                if op in ("I", "U"):
                    if has_row:
                        if op == "U" and pd.isna(ev_amount):
                            # NULL amount on update leaves existing amount unchanged.
                            pass
                        else:
                            amount = ev_amount
                        status = ev_status
                    else:
                        # Create the row from scratch; amount taken as-is (NULL stays NULL).
                        status = ev_status
                        amount = ev_amount
                        has_row = True
                        had_row_ever = True
                    last_seq = seq
                    last_applied_op = op
                    last_applied_seq = seq
                elif op == "D":
                    if has_row:
                        has_row = False
                        last_applied_op = op
                        last_applied_seq = seq
                    # D on a missing order does nothing: no state change,
                    # and it is NOT recorded as the "last applied event".
                    # (fall through without touching last_applied_*)

        if has_row:
            new_state_rows.append(
                {
                    "order_id": oid,
                    "status": status,
                    "amount": amount,
                    "last_seq": last_seq,
                }
            )

        if had_row_ever and last_applied_op == "D":
            tombstone_rows.append(
                {
                    "order_id": oid,
                    "deleted_seq": last_applied_seq,
                }
            )

    new_state = pd.DataFrame(
        new_state_rows, columns=["order_id", "status", "amount", "last_seq"]
    )
    tombstones = pd.DataFrame(
        tombstone_rows, columns=["order_id", "deleted_seq"]
    )

    if not new_state.empty:
        new_state["order_id"] = new_state["order_id"].astype("int64")
        new_state["last_seq"] = new_state["last_seq"].astype("int64")
        new_state["amount"] = new_state["amount"].astype("float64")
    else:
        new_state = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "status": pd.Series(dtype="object"),
                "amount": pd.Series(dtype="float64"),
                "last_seq": pd.Series(dtype="int64"),
            }
        )

    if not tombstones.empty:
        tombstones["order_id"] = tombstones["order_id"].astype("int64")
        tombstones["deleted_seq"] = tombstones["deleted_seq"].astype("int64")
    else:
        tombstones = pd.DataFrame(
            {
                "order_id": pd.Series(dtype="int64"),
                "deleted_seq": pd.Series(dtype="int64"),
            }
        )

    return {"new_state": new_state, "tombstones": tombstones}
